policies:
create policy "Users can read own notifications" on public.notifications as permissive for select to authenticated using ((user_id IN ( SELECT profiles.id_auto
   FROM profiles
  WHERE (profiles.id = auth.uid()))));

create policy "Users can update own notifications" on public.notifications as permissive for update to authenticated using ((user_id IN ( SELECT profiles.id_auto
   FROM profiles
  WHERE (profiles.id = auth.uid()))));

create policy "Users can view own notifications" on public.notifications as permissive for select to public using ((user_id = ( SELECT profiles.id_auto
   FROM profiles
  WHERE (profiles.id = auth.uid()))));

create policy "Admins read all push tokens" on public.push_tokens as permissive for select to authenticated using ((EXISTS ( SELECT 1
   FROM profiles
  WHERE ((profiles.id = auth.uid()) AND (profiles.role = ANY (ARRAY['super_admin'::text, 'compete_admin'::text]))))));

create policy "Admins can view all reports" on public.reports as permissive for select to authenticated using ((EXISTS ( SELECT 1
   FROM profiles
  WHERE ((profiles.id = auth.uid()) AND (profiles.role = ANY (ARRAY['super_admin'::text, 'compete_admin'::text]))))));
